--
-- Table structure for table `chat_messages`
--

DROP TABLE IF EXISTS `chat_messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `chat_messages` (
  `id` int NOT NULL AUTO_INCREMENT,
  `conversation_id` int NOT NULL,
  `sender_user_id` int NOT NULL,
  `sender_role` enum('BUYER','SUPPLIER','SUPER_ADMIN','SYSTEM') COLLATE utf8mb4_unicode_ci NOT NULL,
  `sender_admin_id` int DEFAULT NULL,
  `is_on_behalf_of_supplier` tinyint(1) NOT NULL DEFAULT '0',
  `is_internal_admin_note` tinyint(1) NOT NULL DEFAULT '0',
  `message_type` enum('TEXT','ATTACHMENT','OFFER','SYSTEM') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEXT',
  `message_body` text COLLATE utf8mb4_unicode_ci,
  `delivery_status` enum('SENT','DELIVERED','READ') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SENT',
  `read_at` datetime DEFAULT NULL,
  `has_restricted_contact` tinyint(1) NOT NULL DEFAULT '0',
  `metadata` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_conversation` (`conversation_id`),
  KEY `idx_sender_user` (`sender_user_id`),
  KEY `idx_delivery_status` (`delivery_status`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_internal_note` (`is_internal_admin_note`),
  CONSTRAINT `fk_chat_messages_conv` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=128 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

