INSERT INTO `cms_pages` VALUES (1,'Cricket Bats & Pads','cricket-bats-pads','Cricket Bats & Pads Wholesale — Sports Junction B2B','Source direct factory English willow bats, Kashmir willow bats, protective batting leg pads, and wicketkeeping gear from verified sports manufacturers.','TOP_SECTORS','<h2>Wholesale Cricket Equipment Manufacturing</h2><p>Sports Junction connects verified global cricket equipment importers, brands, and sporting academies with direct tier-1 manufacturing hubs specializing in English and Kashmir willow cricket bats, batting leg guards, wicketkeeping equipment, and protective gear engineered to international test match standards.</p><p>All manufacturers adhere to strict wood-curing standards, compression testing, and grain alignment inspection to ensure top durability and performance.</p>','/category/cricket-and-field-sports',1,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(2,'Match Footballs','match-footballs','Match Footballs Factory Direct — Sports Junction B2B','Bulk supply of FIFA standard match footballs, thermo-bonded match balls, hand-stitched training balls, and custom OEM branded soccer balls.','TOP_SECTORS','<h2>Professional Match & Training Football Production</h2><p>Discover direct OEM and ODM football manufacturers producing FIFA-standard match balls, thermo-bonded PU casing balls, hand-stitched training soccer balls, and custom club branded inflatables. Certified for low water absorption, rebound accuracy, and seam durability under intense tournament conditions.</p>','/category/football-and-inflatables',2,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(3,'Agility Hurdles & Ladders','agility-hurdles-ladders','Agility Hurdles & Ladders Wholesale — Sports Junction','High-impact agility hurdles, speed ladders, coordination grids, and coaching training gear direct from certified sporting goods factories.','TOP_SECTORS','<h2>High-Performance Speed & Agility Equipment</h2><p>Precision-molded shatterproof agility hurdles, flat-rung nylon speed ladders, agility poles, and reaction training accessories tailored for professional athletic teams, schools, and fitness training academies. Available for custom color branding and bulk container shipments.</p>','/category/agility-and-speed-training',3,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(4,'Commercial Gym Equipment','commercial-gym-equipment','Commercial Gym Equipment Wholesale — Sports Junction','Direct factory heavy-duty strength equipment, selectorized gym machines, Olympic bars, bumper plates, and functional cross-training rigs.','TOP_SECTORS','<h2>Heavy-Duty Commercial Fitness Equipment</h2><p>Engineered for high-volume health clubs, athletic training centers, and commercial fitness franchises. Our verified manufacturing partners produce heavy-gauge laser-cut steel racks, precision plate-loaded machines, Olympic urethane bumper plates, and ergonomic cardiovascular machines backed by commercial warranties.</p>','/category/sports-and-fitness',4,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(5,'Sportswear & Uniforms','sportswear-uniforms','Sportswear & Uniforms Custom OEM — Sports Junction','OEM custom sublimated jerseys, technical sports uniforms, tracksuits, compression wear, and team kits direct from verified apparel factories.','TOP_SECTORS','<h2>Custom Technical Teamwear & Athletic Apparel</h2><p>Full-coverage sublimation printing, moisture-wicking quick-dry fabrics, antimicrobial treatment, and bespoke sizing for team uniforms across football, cricket, basketball, and track sports. Low MOQs with rapid turnaround on private label OEM manufacturing orders.</p>','/category/apparel-and-accessories',5,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(6,'Direct Factory Catalog','direct-factory-catalog','Direct Factory Catalog — Sports Junction Wholesale','Browse verified sports factory products, compare FOB pricing, and connect directly with certified manufacturing facilities worldwide.','SOURCING','<h2>Direct Factory Product Directory</h2><p>Explore thousands of verified sporting goods listings direct from vetted factories across Asia and global export hubs. Skip intermediate broker markups, inspect actual factory capabilities, and initiate direct trade negotiations with confidence.</p>','/products',1,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(7,'Request for Quotation (RFQ)','request-for-quotation','Request for Quotation (RFQ) — Sports Junction B2B','Broadcast your custom sports goods specifications to certified manufacturers and receive competitive wholesale quotations within 24 hours.','SOURCING','<h2>Submit a Direct Request for Quotation (RFQ)</h2><p>Can’t find exactly what you need? Post your exact product specifications, tech packs, target order volume, and destination port. Sports Junction matches your requirement with qualified verified suppliers who submit direct FOB and CIF factory bids within 24 business hours.</p>','/page/request-for-quotation',2,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(8,'Contact Us & Support','contact-us-support','Contact Us & Support — Sports Junction','Get in touch with the Sports Junction sourcing team, vendor verification officers, and international trade assistance desk.','SOURCING','<h2>Global Sourcing & Trade Support</h2><p>Our dedicated team of trade specialists, sourcing consultants, and supplier verification agents is ready to assist with custom sourcing briefs, factory audits, dispute resolution, and platform inquiries.</p>','/contact',3,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(9,'Container Freight Logistics','container-freight-logistics','Container Freight Logistics — Sports Junction','Comprehensive FCL and LCL container shipping, door-to-port freight forwarding, customs clearance, and marine cargo insurance solutions.','SOURCING','<h2>International Freight Forwarding & Logistics</h2><p>Seamlessly move sports equipment shipments from factory doors to your destination warehouse. We coordinate Full Container Load (FCL) and Less than Container Load (LCL) sea freight, expedited air cargo, export customs documentation, and bill of lading releases with world-class maritime logistics partners.</p>','/page/container-freight-logistics',4,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(10,'XML Sitemap','xml-sitemap','XML Sitemap — Sports Junction B2B Platform','Complete search engine indexing sitemap covering product catalogues, verified suppliers, categories, and manufacturing resources.','SOURCING','<h2>Sports Junction Search Index & Sitemap</h2><p>Complete indexing directory for search engine crawlers and automated discovery agents to index our live factory products, categories, subcategories, and trade documentation.</p>','/sitemap.xml',5,1,'2026-10-17 14:16:06','2026-10-17 14:16:06'),(14,'Terms & Manufacturing SLA','terms-manufacturing-sla','Terms & Manufacturing SLA — Sports Junction','Platform terms of service, manufacturing quality service level agreements, trade dispute procedures, and buyer protection guidelines.','PLATFORM_ADMIN','<h2>Manufacturing Service Level Agreement (SLA) & Trade Terms</h2><p>Sports Junction enforces rigorous manufacturing quality standards across all supplier listings. Our policies govern acceptable defect rates (AQL 2.5 standard), on-time dispatch guidelines, pre-shipment quality inspection protocols, and verified direct commercial terms agreed directly between buyers and verified suppliers under proforma invoice agreements.</p>','/page/terms-manufacturing-sla',4,1,'2026-10-17 14:16:06','2026-10-17 17:11:07'),(18,'Seller & Manufacturer Agreement','seller-agreement','Seller & Manufacturer Master Agreement — Sports Junction','Official Seller Agreement, manufacturing compliance requirements, catalog publishing rules, and B2B terms for Sports Junction manufacturers.','PLATFORM_ADMIN','<h2>1. Manufacturer & Supplier Eligibility</h2><p>Sports Junction operates as an authorized B2B sports equipment manufacturing marketplace. By applying for or maintaining a manufacturer account, you represent and warrant that your facility holds authentic business registration licenses, factory inspection certifications, and legal manufacturing rights in your jurisdiction.</p><h2>2. Facility Verification & Super Admin Approval</h2><p>All supplier registrations remain in <strong>Pending Verification</strong> status until verified via business email OTP and subsequently reviewed by the Super Admin trade desk. The Super Admin reserves the right to request proof of factory address, export licenses, or tax documentation before approving any seller profile. Unapproved suppliers cannot upload, publish, or market products.</p><h2>3. Catalog Publishing & Moderation</h2><p>All product additions, bulk spreadsheet imports, and specification revisions undergo mandatory moderation by the Super Admin catalog desk. Products must meet industrial sports quality standards, declare accurate MOQ (Minimum Order Quantity), specify authentic wholesale price tiers in USD, and provide true export packaging dimensions.</p><h2>4. Inquiry & RFQ Fulfillment</h2><p>Suppliers agree to acknowledge and respond to buyer inquiries, requests for quotation (RFQs), and sample requests within 24 to 48 business hours. Suppliers must honor quoted specifications, lead times, and manufacturing tolerances agreed during direct chat negotiations.</p><h2>5. Intellectual Property & Brand OEM Protection</h2><p>Suppliers must respect third-party intellectual property, trademarks, and patents. Fabricating counterfeit sporting goods, misrepresenting brand authorizations, or unauthorized use of international sports federation marks will result in immediate suspension, listing removal, and referral to trade authorities.</p><h2>6. Suspension & Account Termination</h2><p>Sports Junction may suspend or terminate manufacturer facilities that engage in fraudulent representations, fail quality audits, attempt off-platform fee avoidance, or breach agreed manufacturing SLAs.</p>',NULL,5,1,'2026-10-17 15:48:59','2026-10-17 15:52:33');
/*!40000 ALTER TABLE `cms_pages` ENABLE KEYS */;
UNLOCK TABLES;

