INSERT INTO `products` VALUES (1,1,3,5,'Grade-A English Willow Cricket Bat','grade-a-english-willow-cricket-bat','SJ-CRK-ENG01','Meerut Pro Series','Hand-crafted Grade 1 English Willow cricket bat with balanced pick up and thick edges.','Crafted from selected hand-split Grade 1 English willow grown in sustainable UK forests and seasoned in Meerut. Features massive contoured 40mm edges, balanced light pick up, semi-oval 12-piece cane handle with rubber grip, and toe guard protection.','https://images.unsplash.com/photo-1531415074868-036b1c57e329?auto=format&fit=crop&w=800&q=80',NULL,45.00,55.00,55.00,'USD','INR',3800.00,1,25,1,500,1,50.00,'Grade-1 English Willow, 12-Piece Cane Handle','Natural Wood, Black & Blue Grip','Full Size Short Handle (SH)','1160g - 1220g (2.9 - 2.11 lbs)',NULL,1,1,1,1,1,1,1,1,1,'10 - 20 Business Days','Ex-Factory Meerut or FOB Nhava Sheva Port, Mumbai','Tested 5-ply export corrugated cartons with corner protectors','PUBLISHED','APPROVED',NULL,NULL,NULL,NULL,NULL,1,2,1,'2026-10-10 13:10:51','2026-10-17 16:07:12'),(2,2,4,7,'FIFA Quality Pro Synthetic Leather Football','fifa-quality-pro-synthetic-leather-football','SJ-BALL-FB02','Jalandhar Match Elite','Thermally bonded 32-panel FIFA standard size 5 football made with Japanese PU.','Engineered in Jalandhar leather & sports cluster. 32-panel aerodynamic design made with textured microfiber PU synthetic leather, 4-ply poly-cotton lining, high-rebound butyl bladder for maximum air retention and true flight precision.','https://images.unsplash.com/photo-1579952363873-27f3bade9f55?auto=format&fit=crop&w=800&q=80',NULL,8.50,10.00,10.00,'USD','INR',720.00,1,100,1,2500,1,10.71,'Textured Microfiber Japanese PU, Butyl Bladder','White/Blue/Neon Red','Official Size 5','420g - 440g',NULL,1,1,1,1,1,1,1,2,4,'14 - 25 Business Days','FOB Mundra Port / CIF Worldwide Sea Freight',NULL,'PUBLISHED','APPROVED',NULL,NULL,NULL,NULL,NULL,1,3,0,'2026-10-10 13:10:51','2026-10-15 17:04:14'),(3,1,6,3,'Adjustable Agility Tra